function stagger(fns: (() => void)[], gapMs = 280) {
  const timeouts: ReturnType<typeof setTimeout>[] = [];
  fns.forEach((fn, i) => {
    timeouts.push(setTimeout(fn, i * gapMs));
  });
  return () => timeouts.forEach(clearTimeout);
}

